  .v-check:where(
    [data-slot="checkbox"],
    [data-slot^="checkbox-"]
  ).-block[data-state="checked"] {
  background: var(--v-beige-2);
}
:root[data-mode="dark"]
  .v-check:where([data-slot="checkbox"], [data-slot^="checkbox-"]).-block {
  background: var(--v-beige);
}
@keyframes v-tick {
  0% {
    transform: scale(0.8);
    border-radius: 54% 46% 50% 50%/46% 50% 50% 54%;
  }
  55% {
    transform: scale(1.14, 0.94);
    border-radius: 50% 50% 46% 54%/54% 50% 46% 50%;
  }
  80% {
    transform: scale(0.98, 1.04);
  }
  100% {
    transform: scale(1);
    border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="checkbox"],
  [data-slot^="checkbox-"],
  [data-slot="checkbox"]::before,
  [data-slot="checkbox"]::after,
  [data-slot^="checkbox-"]::before,
  [data-slot^="checkbox-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* The button owns keyboard focus; the authored tile remains the visible focus target. */
[data-slot="checkbox"]:focus-visible {
  outline: none;
}
[data-slot="checkbox"]:focus-visible [data-slot="checkbox-indicator"] {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
[data-slot="checkbox"]:active [data-slot="checkbox-indicator"] {
  transform: scale(0.92);
}
[data-slot="checkbox-mark"] {
  display: none;
}

